import {VaultStrategyClient} from './vault-client.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,primary=false)=>`<button type="button" class="lp-button ${primary?'lp-primary':''}" data-vault-action="${esc(action)}">${label}</button>`;
const date=n=>new Date(n*1000).toISOString().replace('T',' ').slice(0,16)+' UTC';

export class VaultStrategyDesk{
 constructor(chain,{onPrepared=()=>{},onError=()=>{}}={}){this.chain=chain;this.client=new VaultStrategyClient(chain);this.onPrepared=onPrepared;this.onError=onError;this.d={vault:'',asset:'',amount:'',beneficiary:'',linear:false,days:'180',cliffDays:'30',id:'',additionalDays:'30'};this.result=null;this.error='';this.busy=false;this.root=null;this.abort=null;this.generation=0;}
 configure({vault,asset,beneficiary}={}){let changed=false;for(const [key,value] of Object.entries({vault,asset,beneficiary})){if(value&&value!==this.d[key]){this.d[key]=value;changed=true;}}if(changed){this.result=null;this.generation++;this.chain.invalidate?.();}return this;}
 field(key,label,help=''){return `<div class="lp-field"><label for="vault-${key}">${label}</label><input id="vault-${key}" data-vault-field="${key}" value="${esc(this.d[key])}" autocomplete="off" spellcheck="false">${help?`<small>${help}</small>`:''}</div>`;}
 render(context){if(context)this.configure(context);const connected=!!this.chain.address,payer=this.chain.payer||this.chain.address;
  return `<section class="lp-studio lp-vault"><h3>Give your assets a schedule.</h3><p>Lock retained tokens, liquidity shares or native currency to a beneficiary you choose. The fixed recipient and release dates are enforced by the existing TimeVault contract.</p>
   ${!connected?'<p class="lp-attention">Connect through the launch desk to read balances and prepare a lock.</p>':`<p class="lp-note">Funding account: ${esc(payer)}. ${this.chain.execution?.mode==='nft'?'The selected NFT account supplies the assets.':'The connected wallet supplies the assets.'}</p>`}
   ${this.field('vault','Verified TimeVault address','Use the TimeVault installed in a sealed Genesis ledger. Community infrastructure setup can deploy and install it; no deployment is assumed here.')}
   <div class="lp-fields">${this.field('asset','Token or LP-share address','Use the all-zero address for native currency. Decimals and balances are read from the deployed asset.')}${this.field('amount','Amount to lock')}</div>
   ${this.field('beneficiary','Fixed beneficiary',`Leave empty to use the funding account${payer?': '+esc(payer):''}. An NFT account beneficiary makes the release right follow NFT ownership; selling the NFT cannot accelerate the schedule.`)}
   <label class="lp-check"><input type="checkbox" data-vault-field="linear" ${this.d.linear?'checked':''}> Release linearly after a cliff</label>
   <div class="lp-fields">${this.field('days','Duration · days','The reviewed schedule starts five minutes after preparation. Sign before its start.')}${this.d.linear?this.field('cliffDays','Initial cliff · days','Before the cliff, nothing releases. After it, vested amounts include elapsed time since the schedule start.'):''}</div>
   <p class="lp-note">A cliff lock releases all assets at its end. Linear vesting releases progressively. There is no administrator or early withdrawal. Locking LP shares also locks their redemption principal and proportional LP fees; it does not create separate fee-only withdrawal rights.</p>
   <div class="lp-actions">${button('deposit','Review lock & funding',true)}${button('list','Read beneficiary’s locks')}</div>
   <details><summary>Find an existing lock or extend a cliff</summary><div class="lp-fields">${this.field('id','Lock ID')}${this.field('additionalDays','Additional days')}</div><div class="lp-actions">${button('read','Read this lock')}${button('release','Review release')}${button('extend','Review extension')}</div><p class="lp-note">Anyone can release vested assets, always to the original beneficiary. Only that beneficiary may extend an unexpired cliff lock. Linear schedules cannot be extended through this contract.</p></details>
   <p class="lp-message" role="status" aria-live="polite" data-vault-status>${esc(this.error|| (this.busy?'Reading vault state…':''))}</p><div data-vault-result>${this.results()}</div>
  </section>`;
 }
 results(){const locks=this.result?.locks||(this.result?[this.result]:[]);if(!this.result)return '';return `<h4>Assets and release rights</h4>${this.result.total?`<p class="lp-note">${esc(this.result.total)} locks for ${esc(this.result.beneficiary)}. Showing ${locks.length}${this.result.next!==null&&this.result.next!==undefined?' · more available on the next page':''}.</p>`:''}${locks.map(l=>`<div class="lp-recipient"><h5>Lock ${esc(l.id)} · ${esc(l.formatted.amount)} ${esc(l.symbol)}</h5><div class="lp-fact"><span>Beneficiary</span><strong>${esc(l.beneficiary)}</strong></div><div class="lp-fact"><span>Schedule</span><strong>${l.linear?'Linear vesting':'Cliff lock'}<br>${date(l.start)} → ${date(l.end)}</strong></div><div class="lp-fact"><span>Cliff</span><strong>${date(l.cliff)}</strong></div><div class="lp-fact"><span>Releasable now</span><strong>${esc(l.formatted.releasable)} ${esc(l.symbol)}</strong></div><div class="lp-fact"><span>Previously released</span><strong>${esc(l.formatted.released)} ${esc(l.symbol)}</strong></div>${BigInt(l.releasable)>0n?button('release:'+l.id,'Review release to beneficiary'):''}</div>`).join('')||'<p>No locks found for this beneficiary.</p>'}${this.result.next!==null&&this.result.next!==undefined?button('page:'+this.result.next,'Read next page'):''}`;}
 mount(root){this.unmount();this.root=root;this.abort=new AbortController();const signal=this.abort.signal;root.addEventListener('input',e=>{const key=e.target.dataset.vaultField;if(key&&key in this.d){this.d[key]=key==='linear'?e.target.checked:e.target.value;this.generation++;this.chain.invalidate?.();if(['vault','beneficiary'].includes(key)){this.result=null;this.refreshResult();}if(key==='linear')this.redraw();}},{signal});root.addEventListener('click',e=>{const b=e.target.closest('[data-vault-action]');if(!b)return;e.preventDefault();this.action(b.dataset.vaultAction).catch(error=>{this.error=error.message;this.onError(error);this.refreshResult();});},{signal});}
 unmount(){this.abort?.abort();this.abort=null;this.root=null;this.generation++;}
 redraw(){if(!this.root)return;const root=this.root;root.innerHTML=this.render();this.mount(root);}
 refreshResult(){if(!this.root)return;const status=this.root.querySelector('[data-vault-status]'),result=this.root.querySelector('[data-vault-result]');if(status)status.textContent=this.error||(this.busy?'Reading vault state…':'');if(result)result.innerHTML=this.results();}
 async action(action){if(this.busy)return;this.busy=true;this.error='';this.refreshResult();const d={...this.d},generation=this.generation;try{
   let plan,result;if(action==='deposit')plan=await this.client.deposit({...d,asset:d.asset||'0x'+'0'.repeat(40)});
   else if(action==='release'||action.startsWith('release:'))plan=await this.client.release({vault:d.vault,id:action.includes(':')?action.split(':')[1]:d.id});
   else if(action==='extend')plan=await this.client.extend(d);
   else if(action==='read')result=await this.client.read(d);
   else if(action==='list'||action.startsWith('page:'))result=await this.client.list({...d,beneficiary:d.beneficiary||undefined,offset:action.includes(':')?action.split(':')[1]:0});
   if(generation!==this.generation){if(plan&&this.chain.plan===plan)this.chain.invalidate();return;}if(result)this.result=result;if(plan)await this.onPrepared(plan);this.refreshResult();
  }finally{this.busy=false;this.refreshResult();}}
}
